namespace Poe2Accessibility.Services
{
    using System;
    using System.Collections.Generic;
    using System.IO;
    using System.Text.Json;
    using System.Text.Json.Serialization;
    using Poe2Accessibility.Models;

    /// <summary>
    ///     Offline knowledge of the game's authored menus, generated by tools/Poe2UiExtract from the
    ///     `metadata/ui/**.ui` scripts (catalog/ui-catalog.json): control id → declared widget class,
    ///     text key, focusability, tab order. Ids repeat across screens, so lookups are by id only and the
    ///     class is the most common one for that id.
    /// </summary>
    public sealed class UiCatalog
    {
        private readonly Dictionary<string, Entry> byId = new(StringComparer.OrdinalIgnoreCase);

        public sealed record Entry(string Id, string ResolvedClass, UiRole Role, bool? Focusable, int Screens);

        public int Count => this.byId.Count;

        /// <summary>Loads the catalog; an absent or broken file yields an empty catalog (heuristics take over).</summary>
        public static UiCatalog Load(string path, PluginLog log)
        {
            var catalog = new UiCatalog();
            try
            {
                if (!File.Exists(path))
                {
                    log.Warn($"UI catalog not found at {path}; using name heuristics only");
                    return catalog;
                }

                var document = JsonSerializer.Deserialize<CatalogFile>(File.ReadAllText(path), JsonOptions);
                var classVotes = new Dictionary<string, Dictionary<string, int>>(StringComparer.OrdinalIgnoreCase);
                var focusVotes = new Dictionary<string, bool?>(StringComparer.OrdinalIgnoreCase);
                var screens = new Dictionary<string, HashSet<string>>(StringComparer.OrdinalIgnoreCase);
                foreach (var control in document?.Controls ?? new List<CatalogControl>())
                {
                    if (string.IsNullOrEmpty(control.Id))
                    {
                        continue;
                    }

                    var votes = classVotes.TryGetValue(control.Id, out var v) ? v : classVotes[control.Id] = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);
                    var cls = control.ResolvedClass ?? control.ClassName ?? string.Empty;
                    votes[cls] = votes.TryGetValue(cls, out var n) ? n + 1 : 1;
                    if (control.Focusable.HasValue)
                    {
                        focusVotes[control.Id] = control.Focusable;
                    }

                    (screens.TryGetValue(control.Id, out var s) ? s : screens[control.Id] = new HashSet<string>()).Add(control.Screen ?? string.Empty);
                }

                foreach (var (id, votes) in classVotes)
                {
                    var best = string.Empty;
                    var bestCount = -1;
                    foreach (var (cls, count) in votes)
                    {
                        if (count > bestCount)
                        {
                            best = cls;
                            bestCount = count;
                        }
                    }

                    catalog.byId[id] = new Entry(id, best, RoleFromClass(best), focusVotes.TryGetValue(id, out var f) ? f : null, screens[id].Count);
                }

                log.Info($"UI catalog loaded: {catalog.byId.Count} control ids from {document?.SourceCount ?? 0} scripts");
            }
            catch (Exception ex)
            {
                log.Error("UI catalog unreadable; using name heuristics only", ex);
            }

            return catalog;
        }

        public bool TryGet(string controlId, out Entry entry) =>
            this.byId.TryGetValue(controlId, out entry!);

        /// <summary>Declared widget class → spoken role. Classes come from the .ui scripts (docs/research/ui-layouts.md).</summary>
        public static UiRole RoleFromClass(string className)
        {
            if (className.Contains("ComboBox", StringComparison.OrdinalIgnoreCase))
            {
                return UiRole.ComboBox;
            }

            if (className.Contains("CheckBox", StringComparison.OrdinalIgnoreCase))
            {
                return UiRole.CheckBox;
            }

            if (className.Contains("TextBox", StringComparison.OrdinalIgnoreCase))
            {
                return UiRole.TextField;
            }

            if (className.Contains("Button", StringComparison.OrdinalIgnoreCase))
            {
                return UiRole.Button;
            }

            if (className.Equals("Label", StringComparison.OrdinalIgnoreCase))
            {
                return UiRole.Label;
            }

            return UiRole.Unknown;
        }

        private static readonly JsonSerializerOptions JsonOptions = new() { PropertyNameCaseInsensitive = true };

        private sealed class CatalogFile
        {
            [JsonPropertyName("sourceCount")]
            public int SourceCount { get; set; }

            [JsonPropertyName("controls")]
            public List<CatalogControl> Controls { get; set; } = new();
        }

        private sealed class CatalogControl
        {
            [JsonPropertyName("id")]
            public string? Id { get; set; }

            [JsonPropertyName("className")]
            public string? ClassName { get; set; }

            [JsonPropertyName("resolvedClass")]
            public string? ResolvedClass { get; set; }

            [JsonPropertyName("screen")]
            public string? Screen { get; set; }

            [JsonPropertyName("focusable")]
            public bool? Focusable { get; set; }
        }
    }
}
